Method.Source:
public void build()
{
    super();

    df_prodId = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVAReportFinishedBasketContract, parmProdId));
    df_prodId.enabled(false);
    df_itemId = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVAReportFinishedBasketContract,parmItemId));
    df_itemid.enabled(false);

}
